// Usage: node render.js <code-file> <out.html> [label]
// Embeds any text file as JSON in a single self-contained page; the page highlights it in the browser.
const fs = require('fs');

const [src, out, labelArg] = process.argv.slice(2);
if (!src || !out) {
  console.error('usage: node render.js <code-file> <out.html> [label]');
  process.exit(2);
}

const code = fs.readFileSync(src, 'utf8');
const label = labelArg || require('path').basename(src);
// Keep the JSON safe inside a <script> element.
const payload = JSON.stringify({ label, code }).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026');

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Code view</title>
<style>
:root{--bg:#fbfbf9;--fg:#1d1f21;--card:#eeeeea;--line:#d6d6d0;--kw:#7a3e9d;--str:#2e7d32;--num:#b35900;--com:#7b7f86;--fn:#1f5fa8}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--bg:#15171a;--fg:#e4e6ea;--card:#21242a;--line:#343841;--kw:#c792ea;--str:#a5d6a7;--num:#f9a85a;--com:#7d8590;--fn:#82aaff}}
:root[data-theme="dark"]{--bg:#15171a;--fg:#e4e6ea;--card:#21242a;--line:#343841;--kw:#c792ea;--str:#a5d6a7;--num:#f9a85a;--com:#7d8590;--fn:#82aaff}
html,body{margin:0;padding:0;background:var(--bg);color:var(--fg);overflow-x:hidden}
body{font-family:ui-sans-serif,system-ui,sans-serif;min-height:100vh}
#bar{position:sticky;top:0;display:flex;justify-content:space-between;gap:.5em;padding:.4em .7em;background:var(--card);border-bottom:1px solid var(--line);font-size:13px}
#bar span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#wrap{padding:.6em .7em 2em}
pre{margin:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:clamp(11px,2.3vw,15px);line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;max-width:100%;tab-size:4}
.kw{color:var(--kw);font-weight:600}.str{color:var(--str)}.num{color:var(--num)}.com{color:var(--com);font-style:italic}.fn{color:var(--fn)}
</style>
</head>
<body>
<div id="bar"><span id="lbl"></span><span id="cnt"></span></div>
<div id="wrap"><pre id="code"></pre></div>
<script type="application/json" id="payload">${payload}</script>
<script>
(function () {
  var KW = new Set(('abstract as async await break case catch class const continue debugger default delete do else enum export extends ' +
    'false finally for from function get if implements import in instanceof interface let new null of package private protected ' +
    'public return set static super switch this throw true try type typeof undefined var void while with yield ' +
    'def elif except lambda pass raise None True False and or not is global nonlocal assert del with ' +
    'fn impl mod pub use struct trait match mut ref self Self where loop crate func go chan defer select range fi esac then done ' +
    'SELECT FROM WHERE INSERT UPDATE DELETE JOIN ON AS AND OR NOT NULL CREATE TABLE ORDER BY GROUP LIMIT').split(' '));
  var TOKEN = new RegExp([
    '(\\\\/\\\\*[\\\\s\\\\S]*?(?:\\\\*\\\\/|$))',          // block comment
    '(\\\\/\\\\/[^\\\\n]*|#[^\\\\n]*|--[^\\\\n]*)',          // line comment (//, #, --)
    '("(?:\\\\\\\\.|[^"\\\\\\\\\\\\n])*"?|\\'(?:\\\\\\\\.|[^\\'\\\\\\\\\\\\n])*\\'?|\`(?:\\\\\\\\.|[^\`\\\\\\\\])*\`?)', // strings
    '(\\\\b\\\\d[\\\\d_]*(?:\\\\.\\\\d+)?(?:[eE][+-]?\\\\d+)?\\\\b)',  // numbers
    '(\\\\b[A-Za-z_][A-Za-z0-9_]*\\\\b)'                    // words
  ].join('|'), 'g');

  function esc(s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

  function highlight(text) {
    var out = '', last = 0, m;
    TOKEN.lastIndex = 0;
    while ((m = TOKEN.exec(text))) {
      out += esc(text.slice(last, m.index));
      var t = m[0], cls = '';
      if (m[1] != null || m[2] != null) cls = 'com';
      else if (m[3] != null) cls = 'str';
      else if (m[4] != null) cls = 'num';
      else if (m[5] != null) cls = KW.has(t) ? 'kw' : (/^[A-Z]/.test(t) ? 'fn' : '');
      out += cls ? '<span class="' + cls + '">' + esc(t) + '</span>' : esc(t);
      last = m.index + t.length;
    }
    return out + esc(text.slice(last));
  }

  var data = JSON.parse(document.getElementById('payload').textContent);
  document.getElementById('lbl').textContent = data.label;
  var lines = data.code.split('\\n').length;
  document.getElementById('cnt').textContent = lines + ' line' + (lines === 1 ? '' : 's');
  document.title = data.label;
  document.getElementById('code').innerHTML = highlight(data.code);
})();
</script>
</body>
</html>
`;

fs.writeFileSync(out, html);
console.log('wrote ' + out + ' (' + Buffer.byteLength(html) + ' bytes)');

