var htmlLines = data.code.split('\\n').map(highlight);
var pages = [], cur = 0;
// Greedy fit: add whole lines until the next one would overflow the pane; no scrolling.
function fill(from) {
  var end = from;
  pre.innerHTML = '';
  while (end < htmlLines.length) {
    var row = document.createElement('div');
    row.innerHTML = htmlLines[end] || ' ';
    pre.appendChild(row);
    if (wrap.scrollHeight > wrap.clientHeight && end > from) { pre.removeChild(row); break; }
    end++;
  }
  return end;
}
function paginate() {
  pages = [];
  var from = 0;
  while (from < htmlLines.length) { pages.push(from); from = fill(from); }
  show(Math.min(cur, pages.length - 1));
}
function show(i) {
  cur = i;
  fill(pages[i]);
  document.getElementById('pos').textContent = (i + 1) + ' / ' + pages.length;
  document.getElementById('prev').disabled = i === 0;
  document.getElementById('next').disabled = i === pages.length - 1;
}
document.getElementById('prev').onclick = function () { show(cur - 1); };
document.getElementById('next').onclick = function () { show(cur + 1); };
var timer;
window.addEventListener('resize', function () { clearTimeout(timer); timer = setTimeout(paginate, 120); });
